  String toString() {
    return (StringBuffer('DayAnswersCompanion(')
          ..write('day: $day, ')
          ..write('answer: $answer, ')
          ..write('answeredAt: $answeredAt, ')
          ..write('rowid: $rowid')
          ..write(')'))
        .toString();
  }
}

